def is_error(line):
    level = line.split(" ")[2]
    return level in ("ERROR", "FATAL")

print(is_error("2026-11-10 09:40:01 ERROR db: timeout"))
print(is_error("2026-11-10 09:40:02 INFO gateway: ok"))
print(is_error("2026-11-10 09:40:03 FATAL db: too many connections"))

