def to_ms(text):
    if text.endswith("ms"):
        return int(text[:-2])
    return int(text[:-1]) * 1000

print(to_ms("3s"))
print(to_ms("250ms"))
print(to_ms("3s") + to_ms("250ms"))

def service_of(line):
    return line.split(" ")[3].rstrip(":")

assert service_of("2026-11-10 09:40:01 ERROR payment-svc: timeout") == "payment-svc"
assert service_of("2026-11-10 09:40:02 INFO gateway: ok") == "gateway"
assert service_of("2026-11-10 09:40:03 FATAL db: down") == "db"
print("全部通过")

